"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def _sort_key(student: Student) -> str:
    return student.display_name.casefold()

def _missing_emails(roster: List[Student]) -> List[str]:
    return [
        student.display_name
        for student in roster
        if not student.email
    ]

def _check_emails(roster: List[Student]) -> None:
    missing = _missing_emails(roster)
    if missing:
        names = "; ".join(missing)
        raise ValueError(f"no email on file for: {names}")

def _widths(roster: List[Student]) -> Tuple[int, int]:
    names = [student.display_name for student in roster]
    sections = [student.section for student in roster]
    return max(map(len, names)), max(map(len, sections))

def _format_row(
    student: Student, widths: Tuple[int, int]
) -> str:
    name_width, section_width = widths
    name = student.display_name.ljust(name_width)
    section = student.section.ljust(section_width)
    return f"{name}  {section}  {student.email}"

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Sorted, aligned rows. Students need an email."""
    roster = sorted(students, key=_sort_key)
    if not roster:
        raise ValueError("no students to list")
    _check_emails(roster)
    widths = _widths(roster)
    return [
        _format_row(student, widths) for student in roster
    ]
